-- risk: additive
-- 0073: the ZONE_ENVIRONMENT_APPENDED payload carries the zone-day rain
-- quality of migration 0072 (contract docs/contracts/rainfall/zone-day-projection.md):
-- rain_coverage, rain_selected_deveui, rain_policy_version,
-- rain_quality_reasons (a JSON array, never a string holding one) and
-- rain_received_mm. contract_version stays 1; the keys are additive.
-- A row without rain_policy_version is a legacy row: its five keys are sent
-- as null whatever the columns hold. Stored reasons that are not a JSON array
-- are sent as null and never fail the write. The update trigger still fires
-- only when sync_version changes; the projection writer bumps it once per
-- projected change, so a late correction emits exactly one event.
-- Only the two outbox triggers change; no table, column or row is touched.
-- sync-init-fn recreates both triggers at every boot from
-- scripts/sync-trigger-source.json; each CREATE below is byte-identical to
-- that entry, so the boot body and the migrated body agree.
DROP TRIGGER IF EXISTS trg_dp_zone_env_outbox_ai;
CREATE TRIGGER trg_dp_zone_env_outbox_ai AFTER INSERT ON zone_daily_environment FOR EACH ROW WHEN EXISTS ( SELECT 1 FROM sync_link_state WHERE peer_node = 'cloud' AND linked = 1 ) BEGIN INSERT INTO sync_outbox(event_uuid, aggregate_type, aggregate_key, op, payload_json, sync_version, occurred_at, gateway_device_eui) VALUES (lower(hex(randomblob(16))), 'ZONE_ENVIRONMENT', COALESCE((SELECT zone_uuid FROM irrigation_zones WHERE id = NEW.zone_id AND deleted_at IS NULL), 'zone-id:' || NEW.zone_id) || '|' || COALESCE(NEW.date, ''), 'ZONE_ENVIRONMENT_APPENDED', json_object('contract_version', 1, 'zone_id', NEW.zone_id, 'zone_uuid', (SELECT zone_uuid FROM irrigation_zones WHERE id = NEW.zone_id AND deleted_at IS NULL), 'date', NEW.date, 'rainfall_mm', NEW.rainfall_mm, 'flow_liters', NEW.flow_liters, 'rain_source', NEW.rain_source, 'computed_at', NEW.computed_at, 'gateway_device_eui', COALESCE((SELECT gateway_device_eui FROM irrigation_zones WHERE id = NEW.zone_id AND deleted_at IS NULL), NULLIF(trim((SELECT gateway_device_eui FROM sync_link_state WHERE peer_node='cloud')),'')), 'rain_coverage', CASE WHEN NEW.rain_policy_version IS NOT NULL THEN NEW.rain_coverage END, 'rain_selected_deveui', CASE WHEN NEW.rain_policy_version IS NOT NULL THEN NEW.rain_selected_deveui END, 'rain_policy_version', NEW.rain_policy_version, 'rain_quality_reasons', json(CASE WHEN NEW.rain_policy_version IS NOT NULL AND json_valid(NEW.rain_quality_reasons) AND json_type(NEW.rain_quality_reasons) = 'array' THEN NEW.rain_quality_reasons END), 'rain_received_mm', CASE WHEN NEW.rain_policy_version IS NOT NULL THEN NEW.rain_received_mm END, 'sync_version', NEW.sync_version), NEW.sync_version, strftime('%Y-%m-%dT%H:%M:%fZ','now'), COALESCE((SELECT gateway_device_eui FROM irrigation_zones WHERE id = NEW.zone_id AND deleted_at IS NULL), NULLIF(trim((SELECT gateway_device_eui FROM sync_link_state WHERE peer_node='cloud')),''))); END;
DROP TRIGGER IF EXISTS trg_dp_zone_env_outbox_au;
CREATE TRIGGER trg_dp_zone_env_outbox_au AFTER UPDATE ON zone_daily_environment FOR EACH ROW WHEN EXISTS ( SELECT 1 FROM sync_link_state WHERE peer_node = 'cloud' AND linked = 1 ) AND COALESCE(NEW.sync_version,0) <> COALESCE(OLD.sync_version,0) BEGIN INSERT INTO sync_outbox(event_uuid, aggregate_type, aggregate_key, op, payload_json, sync_version, occurred_at, gateway_device_eui) VALUES (lower(hex(randomblob(16))), 'ZONE_ENVIRONMENT', COALESCE((SELECT zone_uuid FROM irrigation_zones WHERE id = NEW.zone_id AND deleted_at IS NULL), 'zone-id:' || NEW.zone_id) || '|' || COALESCE(NEW.date, ''), 'ZONE_ENVIRONMENT_APPENDED', json_object('contract_version', 1, 'zone_id', NEW.zone_id, 'zone_uuid', (SELECT zone_uuid FROM irrigation_zones WHERE id = NEW.zone_id AND deleted_at IS NULL), 'date', NEW.date, 'rainfall_mm', NEW.rainfall_mm, 'flow_liters', NEW.flow_liters, 'rain_source', NEW.rain_source, 'computed_at', NEW.computed_at, 'gateway_device_eui', COALESCE((SELECT gateway_device_eui FROM irrigation_zones WHERE id = NEW.zone_id AND deleted_at IS NULL), NULLIF(trim((SELECT gateway_device_eui FROM sync_link_state WHERE peer_node='cloud')),'')), 'rain_coverage', CASE WHEN NEW.rain_policy_version IS NOT NULL THEN NEW.rain_coverage END, 'rain_selected_deveui', CASE WHEN NEW.rain_policy_version IS NOT NULL THEN NEW.rain_selected_deveui END, 'rain_policy_version', NEW.rain_policy_version, 'rain_quality_reasons', json(CASE WHEN NEW.rain_policy_version IS NOT NULL AND json_valid(NEW.rain_quality_reasons) AND json_type(NEW.rain_quality_reasons) = 'array' THEN NEW.rain_quality_reasons END), 'rain_received_mm', CASE WHEN NEW.rain_policy_version IS NOT NULL THEN NEW.rain_received_mm END, 'sync_version', NEW.sync_version), NEW.sync_version, strftime('%Y-%m-%dT%H:%M:%fZ','now'), COALESCE((SELECT gateway_device_eui FROM irrigation_zones WHERE id = NEW.zone_id AND deleted_at IS NULL), NULLIF(trim((SELECT gateway_device_eui FROM sync_link_state WHERE peer_node='cloud')),''))); END;
